set-variable.value:
#[(vars.responses default []) ++ [{
                            status: 'FAIL',
                            description: 'No Capacities',
                            capacities: null
                          }]]

ee:message.ee:set-payload:
%dw 2.0
output application/json

---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "GET",
	path: "/unifiedPortalConf",
	body: {},
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client-secret'),
	"client_id" : p('mongo-db-sapi.security.client-id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{
		nombre: p('mongo-db-sapi.nombre-franja')
	},
	uriParameters:{

	}
}

%dw 2.0
output application/json

var caps = 
  (payload 
    filter ((item) -> item.status == "PASS" and item.capacities != null)
    flatMap ((item) -> item.capacities)) default []

var groupedByDate = caps groupBy $.date

fun obtenerValor(llave) =
    (vars.timeslot_user filter ($.Llave == llave))[0].Valor default ""


---
{
  items: groupedByDate pluck ((capacities, date) -> {
    date: date,
    areas: [
      {
        label: vars.area[0],
        timeSlots: (capacities groupBy $.time_slot) pluck ((capsByTimeSlot, timeSlot) -> {
          label: timeSlot,
          timeslot_user: obtenerValor(timeSlot as String),
          categories: capsByTimeSlot map (c) -> {
            label: c.work_skill,
            quota: (c.quota default 0) as Number,
            used: ((c.quota default 0) as Number) - ((c.available default 0) as Number)
          }
        })
      }
    ]
  })
}

%dw 2.0
output application/json

var params = vars.parameters
---
{
  ObtenerDisponibilidadAgendas: {
    solicitudDisponibilidadAgenda: {
      DatosSolicitud: {
        FechaAgenda: ((payload.date default "") ++ "T00:00:00.000Z"),
        NumeroOrden: payload.orderNumber default ""
      }
    }
  }
}

%dw 2.0
output application/json

---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "GET",
	path: "/unifiedPortalConf",
	body: {},
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client-secret'),
	"client_id" : p('mongo-db-sapi.security.client-id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{
		nombre: p('mongo-db-sapi.nombre-franja')
	},
	uriParameters:{

	}
}

%dw 2.0
output application/json skipNullOn="everywhere"

var agendas =
    payload."0".payload.ObtenerDisponibilidadAgendasResponse.Resultado.fecha_agendas.DisponibilidadAgenda default []

var franjas =
    payload."1".payload.portal_unificado_conf[0].Parametros default []

var franjasIndex = franjas groupBy $.Llave

fun obtenerValor(llave) =
    franjasIndex[llave][0].Valor default null

---
{
  items: agendas map (agenda) -> {
    date: agenda.date,
    color: agenda.color,
    areas: [
      {
        label: agenda.Zona,
        timeSlots:
          if (isEmpty(agenda.time_slot default null))
            []
          else
            ((agenda.time_slot splitBy ",") distinctBy $)
              map (slot) -> {
                label: slot,
                timeslot_user: obtenerValor(slot),
                categories: []
              }
      }
    ]
  }
}
